def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    ink = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    # Extend marks across gaps on every busy row and column.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == ink]
        if len(cols) >= 3:
            for c in range(cols[0] + 1, cols[-1]):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == ink]
        if len(rows) >= 3:
            for r in range(rows[0] + 1, rows[-1]):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

